// Some portions generated by Codex
import assert from 'node:assert/strict';
import test from 'node:test';
import { labelHoverBridge } from '../../../main/frontend/graph-explorer/graph-hover.ts';

test('label hover bridges cover only the finite gap at the smaller target width', () => {
  const node = {x: 512, y: 164, width: 180, height: 46};
  for (const label of [{x: 355, y: 113, width: 62, height: 23},
    {x: 250, y: 164, width: 62, height: 23}, {x: 512, y: -100, width: 62, height: 23},
    {x: 512, y: 500, width: 2000, height: 10}]) {
    const points = labelHoverBridge(node, label);
    assert.equal(points.length, 4);
    assert.ok(points.every(point => Number.isFinite(point.x) && Number.isFinite(point.y)));
    assert.ok(Math.abs(Math.hypot(points[0].x-points[1].x, points[0].y-points[1].y)
      - Math.min(node.width, node.height, label.width, label.height)) < 1e-8);
    assert.deepEqual(labelHoverBridge(node, label), points, 'geometry is deterministic');
    assert.deepEqual(labelHoverBridge(label, node), [points[2], points[3], points[0], points[1]],
      'reversing the rectangles describes the same bounded corridor');
  }
});

test('touching, overlapping, coincident and invalid targets need no hover bridge', () => {
  const node = {x: 0, y: 0, width: 100, height: 40};
  for (const label of [{...node}, {...node, x: 40}, {...node, x: 100},
    {...node, x: Infinity}, {...node, width: 0}, {...node, height: -1}]) {
    assert.deepEqual(labelHoverBridge(node, label), []);
  }
});
